import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_80
.address_size 64
.visible .entry layernorm_fwd(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 n_total,
    .param .f32 eps
)
{
    .reg .pred p0, p1, p2, p3, p4, p5, p_vec, p_tmp;
    .reg .b32 r_tid, r_ntid, r_idx, r_N, r_s, r_block, r_N4, r_tail, r_i, r_tmp;
    .reg .b64 rd_x, rd_w, rd_b, rd_y, base_x, base_y, addr, off_elems64, off_bytes, idx_bytes, t64;
    .reg .b64 saddr_sum_base, saddr_sumsq_base, saddr_scalar_base, saddr_my_sum, saddr_my_sumsq, saddr_partner;
    .reg .f32 f_val, f_w, f_b, f_mean, f_invstd, f_var, f_tmp, f_eps;
    .reg .f32 fx0, fx1, fx2, fx3, fw0, fw1, fw2, fw3, fb0, fb1, fb2, fb3, fy0, fy1, fy2, fy3;
    .reg .f64 d_sum, d_sumsq, d_val, d_tmp, d_mean, d_ex2, d_var, d_N;
    .shared .align 8 .b8 s_sum[2048];
    .shared .align 8 .b8 s_sumsq[2048];
    .shared .align 4 .b8 s_scalar[8];
    // Load params
    ld.param.u64 rd_x,   [x_ptr];
    ld.param.u64 rd_w,   [w_ptr];
    ld.param.u64 rd_b,   [b_ptr];
    ld.param.u64 rd_y,   [y_ptr];
    ld.param.u32 r_N,    [n_total];
    ld.param.f32 f_eps,  [eps];
    // Thread/block info
    mov.u32 r_tid, %tid.x;
    mov.u32 r_ntid, %ntid.x;
    mov.u32 r_block, %ctaid.x;
    // Compute per-sample base offsets
    mul.wide.u32 off_elems64, r_block, r_N;   // element offset = blockIdx.x * N
    shl.b64 off_bytes, off_elems64, 2;        // bytes = elements * 4
    add.s64 base_x, rd_x, off_bytes;
    add.s64 base_y, rd_y, off_bytes;
    // Initialize accumulators
    mov.f64 d_sum,   0d0000000000000000;
    mov.f64 d_sumsq, 0d0000000000000000;
    // Determine vectorization capability (16B alignment + N>=4) for x,w,b,y
    shr.u32 r_N4, r_N, 2;
    and.b32 r_tail, r_N, 3;
    mov.u64 t64, base_x;
    and.b64 t64, t64, 0xf;
    setp.eq.u64 p2, t64, 0;
    mov.u64 t64, rd_w;
    and.b64 t64, t64, 0xf;
    setp.eq.u64 p3, t64, 0;
    mov.u64 t64, rd_b;
    and.b64 t64, t64, 0xf;
    setp.eq.u64 p4, t64, 0;
    mov.u64 t64, base_y;
    and.b64 t64, t64, 0xf;
    setp.eq.u64 p5, t64, 0;
    setp.gt.u32 p_tmp, r_N4, 0;
    and.pred p_vec, p2, p3;
    and.pred p_vec, p_vec, p4;
    and.pred p_vec, p_vec, p5;
    and.pred p_vec, p_vec, p_tmp;
    // First pass: accumulate sum and sumsq
    @p_vec bra $vec_accum;
    mov.u32 r_idx, r_tid;
$loop1:
    setp.ge.u32 p0, r_idx, r_N;
    @p0 bra $loop1_end;
    mul.wide.u32 idx_bytes, r_idx, 4;
    add.s64 addr, base_x, idx_bytes;
    ld.global.f32 f_val, [addr];
    cvt.f64.f32 d_val, f_val;
    add.f64 d_sum, d_sum, d_val;
    mul.f64 d_tmp, d_val, d_val;
    add.f64 d_sumsq, d_sumsq, d_tmp;
    add.u32 r_idx, r_idx, r_ntid;
    bra $loop1;
$loop1_end:
    bra $after_accum;
$vec_accum:
    // Vectorized accumulation over x
    mov.u32 r_i, r_tid;
$vec_loop1:
    setp.ge.u32 p0, r_i, r_N4;
    @p0 bra $vec_loop1_end;
    mul.wide.u32 idx_bytes, r_i, 16;
    add.s64 addr, base_x, idx_bytes;
    ld.global.v4.f32 {fx0, fx1, fx2, fx3}, [addr];
    cvt.f64.f32 d_val, fx0;
    add.f64 d_sum, d_sum, d_val;
    mul.f64 d_tmp, d_val, d_val;
    add.f64 d_sumsq, d_sumsq, d_tmp;
    cvt.f64.f32 d_val, fx1;
    add.f64 d_sum, d_sum, d_val;
    mul.f64 d_tmp, d_val, d_val;
    add.f64 d_sumsq, d_sumsq, d_tmp;
    cvt.f64.f32 d_val, fx2;
    add.f64 d_sum, d_sum, d_val;
    mul.f64 d_tmp, d_val, d_val;
    add.f64 d_sumsq, d_sumsq, d_tmp;
    cvt.f64.f32 d_val, fx3;
    add.f64 d_sum, d_sum, d_val;
    mul.f64 d_tmp, d_val, d_val;
    add.f64 d_sumsq, d_sumsq, d_tmp;
    add.u32 r_i, r_i, r_ntid;
    bra $vec_loop1;
$vec_loop1_end:
    // Tail elements (if any): threads 0..tail-1 handle one extra scalar
    setp.eq.u32 p0, r_tail, 0;
    @p0 bra $after_accum;
    setp.lt.u32 p1, r_tid, r_tail;
    @!p1 bra $after_accum;
    shl.b32 r_tmp, r_N4, 2;
    add.u32 r_idx, r_tmp, r_tid;
    mul.wide.u32 idx_bytes, r_idx, 4;
    add.s64 addr, base_x, idx_bytes;
    ld.global.f32 f_val, [addr];
    cvt.f64.f32 d_val, f_val;
    add.f64 d_sum, d_sum, d_val;
    mul.f64 d_tmp, d_val, d_val;
    add.f64 d_sumsq, d_sumsq, d_tmp;
$after_accum:
    // Store partials to shared memory
    mov.u64 saddr_sum_base,    s_sum;
    mov.u64 saddr_sumsq_base,  s_sumsq;
    mov.u64 saddr_scalar_base, s_scalar;
    mul.wide.u32 idx_bytes, r_tid, 8;
    add.s64 saddr_my_sum,   saddr_sum_base,   idx_bytes;
    add.s64 saddr_my_sumsq, saddr_sumsq_base, idx_bytes;
    st.shared.f64 [saddr_my_sum],   d_sum;
    st.shared.f64 [saddr_my_sumsq], d_sumsq;
    bar.sync 0;
    // Block-wide reduction
    shr.u32 r_s, r_ntid, 1;
$red_loop:
    setp.eq.u32 p0, r_s, 0;
    @p0 bra $red_end;
    setp.ge.u32 p1, r_tid, r_s;
    @p1 bra $skip_add;
    // Sum: my += partner
    mul.wide.u32 idx_bytes, r_s, 8;
    add.s64 saddr_partner, saddr_my_sum, idx_bytes;
    ld.shared.f64 d_tmp, [saddr_partner];
    ld.shared.f64 d_sum, [saddr_my_sum];
    add.f64 d_sum, d_sum, d_tmp;
    st.shared.f64 [saddr_my_sum], d_sum;
    // Sumsq: my += partner
    add.s64 saddr_partner, saddr_my_sumsq, idx_bytes;
    ld.shared.f64 d_tmp, [saddr_partner];
    ld.shared.f64 d_sumsq, [saddr_my_sumsq];
    add.f64 d_sumsq, d_sumsq, d_tmp;
    st.shared.f64 [saddr_my_sumsq], d_sumsq;
$skip_add:
    bar.sync 0;
    shr.u32 r_s, r_s, 1;
    bra $red_loop;
$red_end:
    // Thread 0 computes mean and invstd
    setp.ne.u32 p0, r_tid, 0;
    @p0 bra $after_scalar;
    // Load totals from shared memory index 0
    ld.shared.f64 d_sum,   [saddr_sum_base];
    ld.shared.f64 d_sumsq, [saddr_sumsq_base];
    cvt.rn.f64.u32 d_N, r_N;
    div.rn.f64 d_mean, d_sum, d_N;      // mean
    div.rn.f64 d_ex2,  d_sumsq, d_N;    // E[x^2]
    mul.rn.f64 d_tmp, d_mean, d_mean;   // mean^2
    sub.rn.f64 d_var, d_ex2, d_tmp;     // var = E[x^2] - mean^2
    // clamp var to >= 0
    setp.lt.f64 p1, d_var, 0d0000000000000000;
    @p1 mov.f64 d_var, 0d0000000000000000;
    cvt.rn.f32.f64 f_mean, d_mean;
    cvt.rn.f32.f64 f_var,  d_var;
    add.rn.f32 f_tmp, f_var, f_eps;
    sqrt.rn.f32 f_tmp, f_tmp;
    rcp.rn.f32  f_invstd, f_tmp;
    st.shared.f32 [saddr_scalar_base],      f_mean;
    st.shared.f32 [saddr_scalar_base+4],    f_invstd;
$after_scalar:
    bar.sync 0;
    // Load scalars
    ld.shared.f32 f_mean,   [saddr_scalar_base];
    ld.shared.f32 f_invstd, [saddr_scalar_base+4];
    // Second pass: normalize, scale, shift, store
    @p_vec bra $vec_norm;
    mov.u32 r_idx, r_tid;
$loop2:
    setp.ge.u32 p0, r_idx, r_N;
    @p0 bra $loop2_end;
    mul.wide.u32 idx_bytes, r_idx, 4;
    // x
    add.s64 addr, base_x, idx_bytes;
    ld.global.f32 f_val, [addr];
    // w
    add.s64 addr, rd_w, idx_bytes;
    ld.global.f32 f_w, [addr];
    // b
    add.s64 addr, rd_b, idx_bytes;
    ld.global.f32 f_b, [addr];
    // y = ((x - mean) * invstd) * w + b
    sub.f32 f_tmp, f_val, f_mean;        // x - mean
    mul.f32 f_tmp, f_tmp, f_invstd;       // (x - mean) * invstd
    mul.f32 f_tmp, f_tmp, f_w;            // * w
    add.f32 f_tmp, f_tmp, f_b;            // + b
    // store
    add.s64 addr, base_y, idx_bytes;
    st.global.f32 [addr], f_tmp;
    add.u32 r_idx, r_idx, r_ntid;
    bra $loop2;
$loop2_end:
    bra $done;
$vec_norm:
    // Vectorized normalize/scale/shift/store
    mov.u32 r_i, r_tid;
$vec_loop2:
    setp.ge.u32 p0, r_i, r_N4;
    @p0 bra $vec_loop2_end;
    mul.wide.u32 idx_bytes, r_i, 16;
    // load x,w,b
    add.s64 addr, base_x, idx_bytes;
    ld.global.v4.f32 {fx0, fx1, fx2, fx3}, [addr];
    add.s64 addr, rd_w, idx_bytes;
    ld.global.v4.f32 {fw0, fw1, fw2, fw3}, [addr];
    add.s64 addr, rd_b, idx_bytes;
    ld.global.v4.f32 {fb0, fb1, fb2, fb3}, [addr];
    // compute y
    sub.f32 f_tmp, fx0, f_mean;
    mul.f32 f_tmp, f_tmp, f_invstd;
    mul.f32 f_tmp, f_tmp, fw0;
    add.f32 fy0,  f_tmp, fb0;
    sub.f32 f_tmp, fx1, f_mean;
    mul.f32 f_tmp, f_tmp, f_invstd;
    mul.f32 f_tmp, f_tmp, fw1;
    add.f32 fy1,  f_tmp, fb1;
    sub.f32 f_tmp, fx2, f_mean;
    mul.f32 f_tmp, f_tmp, f_invstd;
    mul.f32 f_tmp, f_tmp, fw2;
    add.f32 fy2,  f_tmp, fb2;
    sub.f32 f_tmp, fx3, f_mean;
    mul.f32 f_tmp, f_tmp, f_invstd;
    mul.f32 f_tmp, f_tmp, fw3;
    add.f32 fy3,  f_tmp, fb3;
    // store y
    add.s64 addr, base_y, idx_bytes;
    st.global.v4.f32 [addr], {fy0, fy1, fy2, fy3};
    add.u32 r_i, r_i, r_ntid;
    bra $vec_loop2;
$vec_loop2_end:
    // Tail elements (if any): threads 0..tail-1 handle one extra scalar
    setp.eq.u32 p0, r_tail, 0;
    @p0 bra $done;
    setp.lt.u32 p1, r_tid, r_tail;
    @!p1 bra $done;
    shl.b32 r_tmp, r_N4, 2;
    add.u32 r_idx, r_tmp, r_tid;
    mul.wide.u32 idx_bytes, r_idx, 4;
    add.s64 addr, base_x, idx_bytes;
    ld.global.f32 f_val, [addr];
    add.s64 addr, rd_w, idx_bytes;
    ld.global.f32 f_w, [addr];
    add.s64 addr, rd_b, idx_bytes;
    ld.global.f32 f_b, [addr];
    sub.f32 f_tmp, f_val, f_mean;
    mul.f32 f_tmp, f_tmp, f_invstd;
    mul.f32 f_tmp, f_tmp, f_w;
    add.f32 f_tmp, f_tmp, f_b;
    add.s64 addr, base_y, idx_bytes;
    st.global.f32 [addr], f_tmp;
$done:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("layernorm_fwd")
class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        # Match LayerNorm defaults: elementwise_affine=True, weight=1, bias=0, eps=1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self.eps = 1e-5
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        # x shape: (batch, *normalized_shape)
        B = x.shape[0]
        N = 1
        for d in self.normalized_shape:
            N *= int(d)
        y = torch.empty(x.shape, device=x.device, dtype=x.dtype)
        module = _get_ptx_module()
        module.launch(
            "layernorm_fwd",
            grid=(int(B), 1, 1),
            block=(256, 1, 1),
            arguments=[x, self.weight, self.bias, y, u32(int(N)), f32(float(self.eps))],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("layernorm_fwd")

class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        # Match LayerNorm defaults: elementwise_affine=True, weight=1, bias=0, eps=1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        # x shape: (batch, *normalized_shape)
        B = x.shape[0]
        N = 1
        for d in self.normalized_shape:
            N *= int(d)
        y = torch.empty(x.shape, device=x.device, dtype=x.dtype)
        module = _get_ptx_module()
        module.launch(
            "layernorm_fwd",
            grid=(int(B), 1, 1),
            block=(256, 1, 1),
            arguments=[x, self.weight, self.bias, y, u32(int(N)), f32(float(self.eps))],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

